(function(root){
  const defaults={font:'Segoe UI',size:36,color:'#ffffff',outline:'#000000',stroke:3,x:.5,y:.9};
  function style(input={}){return {...defaults,...input};}
  function validate(c){if(typeof c.subtitleText!=='string'||!c.subtitleText.trim()||c.subtitleText.length>10000)throw Error('Texto de subtítulo no válido');const s=style(c.subtitleStyle);if(!['Segoe UI','Arial','Verdana','Georgia'].includes(s.font)||![s.color,s.outline].every(v=>/^#[0-9a-f]{6}$/i.test(v))||!Number.isFinite(s.size)||s.size<12||s.size>96||!Number.isFinite(s.stroke)||s.stroke<0||s.stroke>10||![s.x,s.y].every(v=>Number.isFinite(v)&&v>=0&&v<=1))throw Error('Estilo de subtítulo no válido');}
  const stamp=t=>{const ms=Math.max(0,Math.round(t*1000));return String(Math.floor(ms/3600000)).padStart(2,'0')+':'+String(Math.floor(ms/60000)%60).padStart(2,'0')+':'+String(Math.floor(ms/1000)%60).padStart(2,'0')+','+String(ms%1000).padStart(3,'0');};
  function srt(cues){return [...cues].sort((a,b)=>a.startSeconds-b.startSeconds).map((c,i)=>`${i+1}\n${stamp(c.startSeconds)} --> ${stamp(c.startSeconds+c.durationSeconds)}\n${c.subtitleText.replace(/\r/g,'').trim()}\n`).join('\n');}
  function parse(text){if(typeof text!=='string'||text.length>8*1024*1024)throw Error('SRT demasiado grande');const cues=[],clock=s=>{const p=s.replace(',', '.').split(':').map(Number);return p[0]*3600+p[1]*60+p[2];};for(const block of text.replace(/^\uFEFF/,'').replace(/\r/g,'').trim().split(/\n\s*\n/)){const lines=block.split('\n'),i=lines.findIndex(l=>l.includes('-->'));if(i<0)continue;const match=lines[i].match(/(\d{2,}:\d{2}:\d{2}[,.]\d{3})\s*-->\s*(\d{2,}:\d{2}:\d{2}[,.]\d{3})/);if(!match)throw Error('Tiempo SRT no válido');const startSeconds=clock(match[1]),end=clock(match[2]),subtitleText=lines.slice(i+1).join('\n').trim();if(!subtitleText)continue;if(!Number.isFinite(startSeconds)||end<=startSeconds||end>604800)throw Error('Duración SRT no válida');const cue={startSeconds,durationSeconds:end-startSeconds,subtitleText};validate(cue);cues.push(cue);if(cues.length>10000)throw Error('Demasiados subtítulos');}if(!cues.length)throw Error('El SRT no contiene subtítulos válidos');return cues;}
  function draw(ctx,width,height,cues){for(const cue of cues){const s=style(cue.subtitleStyle),font=s.size*height/720;ctx.save();ctx.globalAlpha=cue.opacity??1;ctx.font=`600 ${font}px "${s.font}"`;ctx.textAlign='center';ctx.textBaseline='bottom';ctx.lineJoin='round';ctx.fillStyle=s.color;ctx.strokeStyle=s.outline;ctx.lineWidth=s.stroke*height/720*2;const lines=[];for(const paragraph of cue.subtitleText.split('\n')){let line='';for(const word of paragraph.split(/\s+/)){if(line&&ctx.measureText(line+' '+word).width>width*.88){lines.push(line);line=word;}else line+=(line?' ':'')+word;}lines.push(line);}const x=s.x*width,y=s.y*height;lines.forEach((text,i)=>{const py=y-(lines.length-1-i)*font*1.2;if(s.stroke)ctx.strokeText(text,x,py,width*.94);ctx.fillText(text,x,py,width*.94);});ctx.restore();}}
  const api={defaults,style,validate,srt,parse,draw};if(typeof module==='object'&&module.exports)module.exports=api;else root.LQTACSubtitleModel=api;
})(typeof window==='undefined'?globalThis:window);
